function.arguments:
{"hypothesis": "Extract the tweak dylib and preference binary and list printable strings that look like flags or hex.", "code": "import tarfile, re
t = tarfile.open('/tmp/deb/data.tar')
for name in ['Library/MobileSubstrate/DynamicLibraries/whyOS.dylib','Library/MobileSubstrate/DynamicLibraries/whyOS.plist']:
    d = t.extractfile(name).read()
    open('/tmp/deb/'+name.split('/')[-1],'wb').write(d)
    print(name, len(d))
d = open('/tmp/deb/whyOS.dylib','rb').read()
strs = re.findall(rb'[\x20-\x7e]{6,}', d)
for s in strs:
    if re.search(rb'flag|hex|ctf|[0-9a-fA-F]{16,}|key|secret|%02x|decode|xor', s, re.I):
        print(s.decode())
print('total strings', len(strs))
"}

