{"hypothesis": "Print all printable strings in the dylib and the preference bundle binary to see the logic.", "code": "import tarfile, re
t = tarfile.open('/tmp/deb/data.tar')
d = open('/tmp/deb/whyOS.dylib','rb').read()
for s in re.findall(rb'[\x20-\x7e]{4,}', d): print(s.decode())
print('----bundle')
b = t.extractfile('Library/PreferenceBundles/whyOSsettings.bundle/whyOSsettings').read()
open('/tmp/deb/bundle','wb').write(b)
for s in re.findall(rb'[\x20-\x7e]{6,}', b)[:80]: print(s.decode())
"}

